  "enunciado": "O tipo predominante de excreta que um grupo animal produz está relacionado com o ambiente onde ele vive. Nesse contexto, os animais podem ser classificados em amoniotélicos, ureotélicos e uricotélicos, de acordo com o principal resíduo nitrogenado que produzem.\n\nQual é o fator ambiental que determina o tipo de resíduo a ser eliminado?",
