  "enunciado": "Na avaliação de riscos em investimentos no setor financeiro, compreender o desvio padrão das taxas de retorno ao longo de um período permite analisar riscos potenciais associados a um investimento. Quanto maior o desvio padrão, maior a variação das taxas de retorno e, consequentemente, maior o risco associado ao investimento. Um desvio padrão mais baixo indica um investimento mais estável e previsível.\nUma classificação de risco de investimento que adota o desvio padrão d índice p como medida para avaliação é:\n- muito baixo: d índice p é menor que 5 por cento;\n- baixo: 5 por cento é menor ou igual a d índice p que é menor que 10 por cento;\n- moderado: 10 por cento é menor ou igual a d índice p que é menor que 20 por cento;\n- alto: 20 por cento é menor ou igual a d índice p que é menor que 30 por cento;\n- muito alto: d índice p é maior ou igual a 30 por cento.\n\nUm investidor analisou, ao longo de cinco meses, as taxas de retorno de um tipo de investimento na bolsa de valores e identificou, respectivamente, retornos mensais de 3 por cento, 15 por cento, 6 por cento, 9 por cento e 12 por cento. Ele pretende aplicar um capital nesse tipo de investimento e adotará o desvio padrão como medida para avaliar a classificação do risco associado.\n\nA classificação do risco desse tipo de investimento é",
  "alternativas": [
   "muito baixo.",
   "baixo.",
   "moderado.",
   "alto.",
   "muito alto."
  ],
