  "enunciado": "Um engenheiro é responsável por acompanhar o processo de controle de produção de uma fábrica de parafusos. Esse processo é considerado sob controle se o comprimento C dos parafusos satisfizer M menos 3d é menor ou igual a C que é menor ou igual a M mais 3d sendo M a média dos comprimentos e d o desvio padrão dos comprimentos dos parafusos. Na última coleta de dados em que o processo foi considerado sob controle, foram obtidos M é igual a 5,0 centímetros e d é igual a 1,2 centímetro.\nCom a chegada de uma nova máquina, a variabilidade dos comprimentos dos parafusos foi reduzida, e o processo foi considerado sob controle. A média dos comprimentos dos parafusos produzidos por essa nova máquina foi 5,6 centímetros, e nenhum desses parafusos teve comprimento menor que a medida mínima, nem maior que a medida máxima dos parafusos produzidos pela máquina anterior.\n\nO desvio padrão, em centímetro, para o novo intervalo deverá ser, no máximo,",
