  "enunciado": "Em um supermercado, uma marca de papel higiênico é comercializada em cinco diferentes tipos de pacotes, contendo quantidades distintas de rolos em cada um. Todos os rolos são de mesma largura e com metragens lineares diversas. Os preços de cada tipo de pacote são distintos, e as especificações são estas:\n\n• tipo 1: pacote contendo 4 rolos, com metragem linear de 60 metros por rolo, ao preço de 4,90 reais;\n• tipo 2: pacote contendo 12 rolos, com metragem linear de 20 metros por rolo, ao preço de 4,50 reais;\n• tipo 3: pacote contendo 16 rolos, com metragem linear de 30 metros por rolo, ao preço de 8,60 reais;\n• tipo 4: pacote contendo 20 rolos, com metragem linear de 30 metros por rolo, ao preço de 11,00 reais;\n• tipo 5: pacote contendo 24 rolos, com metragem linear de 20 metros por rolo, ao preço de 8,70 reais. Um cliente vai a esse supermercado, avalia cada uma das especificações e resolve adquirir um pacote de papel higiênico que tenha o menor preço por metro linear.\n\nQual foi o tipo de pacote adquirido por esse cliente?",
