  "enunciado": "O limite recomendável de carga a ser transportada por um caminhão é 10 000 quilogramas. Ao transportar uma carga que excede em 300 quilogramas esse limite, o consumo de combustível é 2 por cento maior que o consumo observado ao transportar 10 000 quilogramas. Em uma rodovia, o consumo de combustível desse caminhão é proporcional à quilometragem percorrida, quando considerada uma mesma carga transportada. Sabe-se que, transportando 10000 quilogramas por 90 quilômetros nessa rodovia, esse caminhão consome 60 litros de combustível. Suponha que esse caminhão irá transportar uma carga de 10300 quilogramas por 75 quilômetros nessa rodovia.\n\nQuantos litros de combustível esse caminhão consumirá para efetuar esse transporte?",
