  "enunciado": "Visando obter créditos de carbono, uma empresa, emissora de gases de efeito estufa, elabora um projeto de reflorestamento em uma área desmatada. De acordo com o projeto, no primeiro ano serão reflorestados 500 hectares. A partir daí, a cada ano, a área total reflorestada será aumentada em 50 por cento em relação ao ano anterior.\n\nA expressão algébrica que representa a área total reflorestada (A índice n), em hectare, ao final de n anos é",
