  "enunciado": "O automóvel é um bem que se desvaloriza muito rapidamente, quando comparado a outros bens. Após a venda, um automóvel novo já sofre uma grande desvalorização. O histórico de um automóvel novo, vendido por 30000 reais, apresenta os seguintes valores (V) de mercado, após decorridos os períodos indicados a seguir:\n\n• ao final de um ano, 27 000 reais;\n• ao final de dois anos, 24 300 reais;\n• ao final de três anos, 21 870 reais. Esses preços seguiram um modelo exponencial que expressa V em função do número n de ano de uso, pela relação V de n é igual a V índice zero vezes q elevado a n, em que V índice zero é o valor inicial, q é o fator de desvalorização e n é o tempo, em ano, decorrido após a venda. O valor, em milhar de real, com uma casa decimal, que mais se aproxima do valor de mercado desse carro, ao final de seis anos, é",
