  "enunciado": "Uma fábrica utiliza latas cilíndricas como embalagem de seus produtos. Para embalar um novo produto, essa fábrica necessitará de latas cilíndricas com, no mínimo, o triplo da capacidade volumétrica das que estão em uso, e com o menor custo possível. O representante de uma empresa de embalagens disponibilizou para essa fábrica cinco opções de latas, relacionando as medidas das latas novas com as que estão em uso. São elas:\n\n• 1: multiplicar a medida do raio por 6 e manter a da altura;\n• 2: triplicar as medidas da área da base e da altura;\n• 3: triplicar a medida do raio e manter a da altura;\n• 4: manter a medida do raio e triplicar a da altura;\n• 5: triplicar as medidas do raio e da altura. O preço de cada lata é diretamente proporcional à sua capacidade volumétrica.\n\nAs exigências da fábrica são atendidas pelo tipo de lata apresentada na opção",
