  "enunciado": "Um tipo de célula se reproduz constantemente por divisão celular, triplicando sua quantidade a cada duas horas, sob condições ideais de proliferação. Suponha uma quantidade inicial Q índice 0 dessas células sob as condições ideais de proliferação durante um certo período. Qual a representação algébrica da quantidade Q dessas células em função do tempo t, em hora, nesse período?",
