  "enunciado": "O síndico de um condomínio contratou uma empresa para verificar a qualidade da água dos cinco reservatórios que alimentam esses edifícios. A empresa utiliza um teste que fornece o valor de um parâmetro, expresso em pontos que variam de 0 a 100, que indicam a qualidade da água, sendo o valor 0 associado à péssima qualidade e 100 associado à ótima qualidade da água. Quando esse parâmetro assume um valor a partir de 50 pontos, a água é considerada de qualidade adequada. Para os reservatórios 1, 2, 3 e 4, esse parâmetro assumiu, respectivamente, os valores 64, 53, 63 e 64 nesse tipo de teste. Já no reservatório 5, esse parâmetro foi de 20 pontos, reprovando a qualidade da água. Com isso, a água desse reservatório será tratada de modo a aumentar sua qualidade. O síndico pretende que o parâmetro de qualidade da água do reservatório 5 aumente o suficiente para que a média dos parâmetros de qualidade da água dos cinco reservatórios seja, no mínimo, igual a 60 pontos. A quantidade mínima de pontos que o parâmetro da qualidade da água do reservatório 5 deve aumentar é",
