  "enunciado": "Uma faculdade oferece dois cursos diferentes na área de Humanas. Para um aluno ingressar nesses cursos, o vestibular contém questões objetivas e uma redação, e a nota final do candidato é a soma dessas notas, utilizando o seguinte critério de pesos:\n• questões objetivas: peso 1 para o curso 1 e peso 1 para o curso 2;\n• redação: peso 2 para o curso 1 e peso 3 para o curso 2. Um candidato que concorre aos dois cursos obteve nota X nas questões objetivas e nota Y na redação. Para analisar sua nota para o curso 1 e para o curso 2, o candidato representa sua nota com um produto de matrizes A vezes B, em que a matriz A representa os pesos, e a matriz B contém as notas obtidas pelo candidato. A matriz resultante A vezes B é uma matriz coluna, em que, na primeira linha, tem sua nota final para o curso 1 e, na segunda linha, tem sua nota final para o curso 2. Nessas condições, qual representação algébrica gera o resultado final desse candidato nos dois cursos?",
