  "enunciado": "Para obtenção do princípio ativo a partir das folhas de uma planta medicinal, um pesquisador as colocou em um béquer, adicionou água e aqueceu a mistura a 100 graus Celsius. Após dez minutos de aquecimento, a mistura foi separada com auxílio de funil e algodão. A parte líquida, por conter ainda pequenas partículas, foi submetida a um processo de separação a intensa rotação, e o sobrenadante, recolhido para avaliação da atividade biológica.\n\nA sequência dos procedimentos utilizados pelo pesquisador foi:",
