  "enunciado": "Durante uma aula de química, o professor discorre sobre propriedades intensivas e cita como exemplo a concentração. Ele afirma que, para a água pura a 20 graus Celsius, a concentração, em mol por litro, é a mesma em 25,0 mililitros e em 500,0 mililitros. Nessa condição, a densidade da água é igual a 1,0 grama por mililitro, e as massas molares, em grama por mol, do hidrogênio e do oxigênio são, respectivamente, iguais a 1 e 16.\n\nA concentração de água, em mol por litro, em qualquer um desses exemplos, é mais próxima de",
