  "enunciado": "O quadro representa os gastos mensais, em real, de uma família com internet, mensalidade escolar e mesada do filho.\n\nDescrição do Quadro: Gastos com internet: 120; gastos com mensalidade escolar: 700; gastos com mesada do filho: 400\n\nNo início do ano, a internet e a mensalidade escolar tiveram acréscimos, respectivamente, de 20 por cento e 10 por cento. Necessitando manter o valor da despesa mensal total com os itens citados, a família reduzirá a mesada do filho.\n\nQual será a porcentagem da redução da mesada?",
