  "enunciado": "O proprietário de um apartamento decidiu instalar porcelanato no piso da sala. Essa sala tem formato retangular com 3,2 metros de largura e 3,6 metros de comprimento. As peças do porcelanato têm formato de um quadrado com lado medindo 80 centímetros. Esse porcelanato é vendido em dois tipos de caixas, com os preços indicados a seguir.\n• Caixas do tipo A: 4 unidades de piso, R$ 35,00;\n• Caixas do tipo B: 3 unidades de piso, R$ 27,00. Na instalação do porcelanato, as peças podem ser recortadas e devem ser assentadas sem espaçamento entre elas, aproveitando-se ao máximo os recortes feitos. A compra que atende às necessidades do proprietário, proporciona a menor sobra de pisos e resulta no menor preço é",
