  "enunciado": "Uma torneira está gotejando água em um balde com capacidade de 18 litros. No instante atual, o balde se encontra com ocupação de 50 por cento de sua capacidade. A cada segundo caem 5 gotas de água da torneira, e uma gota é formada, em média, por 5 vezes 10 elevado a menos 2 mililitros de água. Quanto tempo, em hora, será necessário para encher completamente o balde, partindo do instante atual?",
