  "enunciado": "Uma empresa de ônibus utiliza um sistema de vendas de passagens que fornece a imagem de todos os assentos do ônibus, diferenciando os assentos já vendidos, por uma cor mais escura, dos assentos ainda disponíveis. A empresa monitora, permanentemente, o número de assentos já vendidos e compara-o com o número total de assentos do ônibus para avaliar a necessidade de alocação de veículos extras.\n\nNa imagem tem-se a informação dos assentos já vendidos e dos ainda disponíveis em um determinado instante.\n\nDescrição da imagem: Imagem do interior de um ônibus com a informação dos assentos já vendidos e dos ainda disponíveis em um determinado instante. Dos 42 assentos, os já vendidos são: 01; 02; 03; 04; 05; 07; 09; 12; 13; 14; 15; 17; 19; 23; 27 e 33.\n\nA razão entre o número de assentos já vendidos e o total de assentos desse ônibus, no instante considerado na imagem, é",
