  "enunciado": "Slackline é um esporte no qual o atleta deve se equilibrar e executar manobras estando sobre uma fita esticada. Para a prática do esporte, as duas extremidades da fita são fixadas de forma que ela fique a alguns centímetros do solo. Quando uma atleta de massa igual a 80 quilogramas está exatamente no meio da fita, essa se desloca verticalmente para baixo, formando um ângulo de 10 graus com a horizontal. Sabe-se que a aceleração da gravidade é igual a 10 metros por segundo ao quadrado, cosseno de 10 graus igual a 0,98 e seno de 10 graus igual a 0,17. Qual é a força que a fita exerce em cada uma das árvores por causa da presença da atleta?",
