  "enunciado": "Um professor aplica, durante os cinco dias úteis de uma semana, testes com quatro questões de múltipla escolha a cinco alunos. Os resultados foram representados na matriz.\n\nDescrição da matriz: Matriz composta por cinco linhas e cinco colunas. Na primeira linha estão os números: 3, 2, 0, 1, 2. Na segunda linha estão os números: 3, 2, 4, 1, 2. Na terceira linha estão os números: 2, 2, 2, 3, 2. Na quarta linha estão os números: 3, 2, 4, 1, 0. Na quinta linha estão os números: 0, 2, 0, 4, 4.\n\nNessa matriz os elementos das linhas de 1 a 5 representam as quantidades de questões acertadas pelos alunos Ana, Bruno, Carlos, Denis e Érica, respectivamente, enquanto que as colunas de 1 a 5 indicam os dias da semana, de segunda-feira a sexta-feira, respectivamente, em que os testes foram aplicados. O teste que apresentou maior quantidade de acertos foi o aplicado na",
  "alternativas": [
   "segunda-feira.",
   "terça-feira.",
   "quarta-feira.",
   "quinta-feira.",
   "sexta-feira."
  ],
