  "enunciado": "Um ciclista quer montar um sistema de marchas usando dois discos dentados na parte traseira de sua bicicleta, chamados catracas. A coroa é o disco dentado que é movimentado pelos pedais da bicicleta, sendo que a corrente transmite esse movimento às catracas, que ficam posicionadas na roda traseira da bicicleta. As diferentes marchas ficam definidas pelos diferentes diâmetros das catracas, que são medidos conforme indicação na figura.\n\nDescrição da figura: A figura representa o disco dentado. O diâmetro do disco dentado indicado na figura é o diâmetro do maior círculo interno desse disco.\n\nO ciclista já dispõe de uma catraca com 7 centímetros de diâmetro e pretende incluir uma segunda catraca, de modo que, à medida em que a corrente passe por ela, a bicicleta avance 50 por cento a mais do que avançaria se a corrente passasse pela primeira catraca, a cada volta completa dos pedais. O valor mais próximo da medida do diâmetro da segunda catraca, em centímetro e com uma casa decimal, é",
