  "enunciado": "Construir figuras de diversos tipos, apenas dobrando e cortando papel, sem cola e sem tesoura, é a arte do origami (ori é igual dobrar; kami é igual papel), que tem um significado altamente simbólico no Japão. A base do origami é o conhecimento do mundo por base do tato. Uma jovem resolveu construir um cisne usando a técnica do origami, utilizando uma folha de papel de 18 centímetros por 12 centímetros. Assim, começou por dobrar a folha conforme a figura.\n\nDescrição da figura: A figura mostra um retângulo ABCD, com os lados AB e CD medindo 18 centímetros e os lados AD e BC medindo 12 centímetros. No lado CD tem um ponto E, o segmento CE é igual a 12 centímetros. A partir do ponto E foi feita uma dobra do vértice D para o interior do retângulo, formando um triângulo retângulo ADE. O lado AE é oposto ao ângulo de 90 graus, os lados AD e DE são adjacentes ao ângulo de 90 graus.\n\nApós essa primeira dobradura, a medida do segmento AE é",
