  "enunciado": "Os alunos de uma turma escolar foram divididos em dois grupos. Um grupo jogaria basquete, enquanto o outro jogaria futebol. Sabe-se que o grupo de basquete é formado pelos alunos mais altos da classe e tem uma pessoa a mais do que o grupo de futebol. A tabela seguinte apresenta informações sobre as alturas dos alunos da turma.\n\nDescrição da tabela: A tabela mostra as informações sobre as alturas dos alunos da turma.\n\nMédia: 1,65; mediana: 1,67 e moda: 1,70.\n\nOs alunos P, J, F e M medem, respectivamente, 1,65 metro, 1,66 metro, 1,67 metro e 1,68 metro, e as suas alturas não são iguais a de nenhum outro colega da sala. Segundo essas informações, argumenta-se que os alunos P, J, F e M jogaram, respectivamente,",
