  "enunciado": "Uma construtora pretende conectar um reservatório central (Rc) em formato de um cilindro, com raio interno igual a 2 metros e altura interna igual a 3,30 metros, a quatro reservatórios cilíndricos auxiliares (R1, R2, R3 e R4), os quais possuem raios internos e alturas internas medindo 1,5 metro. As ligações entre o reservatório central e os auxiliares são feitas por canos cilíndricos com 0,10 metro de diâmetro interno e 20 metros de comprimento, conectados próximos às bases de cada reservatório. Na conexão de cada um desses canos com o reservatório central há registros que liberam ou interrompem o fluxo de água. No momento em que o reservatório central está cheio e os auxiliares estão vazios, abrem-se os quatro registros e, após algum tempo, as alturas das colunas de água nos reservatórios se igualam, assim que cessa o fluxo de água entre eles, pelo princípio dos vasos comunicantes. A medida, em metro, das alturas das colunas de água nos reservatórios auxiliares, após cessar o fluxo de água entre eles, é",
