  "enunciado": "Para construir uma piscina, cuja área total da superfície interna é igual a 40 metros quadrados, uma construtora apresentou o seguinte orçamento:\n• R$ 10 000,00 pela elaboração do projeto;\n• R$ 40 000,00 pelos custos fixos;\n• R$ 2 500,00 por metro quadrado para construção da área interna da piscina. Após a apresentação do orçamento, essa empresa decidiu reduzir o valor de elaboração do projeto em 50 por cento mas recalculou o valor do metro quadrado para a construção da área interna da piscina, concluindo haver a necessidade de aumentá-lo em 25 por cento. Além disso, a construtora pretende dar um desconto nos custos fixos, de maneira que o novo valor do orçamento seja reduzido em 10 por cento em relação ao total inicial. O percentual de desconto que a construtora deverá conceder nos custos fixos é de",
