  "enunciado": "O grafeno é uma forma alotrópica do carbono constituído por uma folha planar (arranjo bidimensional) de átomos de carbono compactados e com a espessura de apenas um átomo. Sua estrutura é hexagonal, conforme a figura.\n\nDescrição da estrutura do grafeno:\n\nA estrutura apresenta uma rede plana formada por vários hexágonos interligados, que contêm, em cada vértice, um átomo de carbono. Cada átomo de carbono está ligado a outros três átomos de carbono presentes nos vértices desses hexágonos.\n\nNesse arranjo, os átomos de carbono possuem hibridação",
