  "enunciado": "O carro flex é uma realidade no Brasil. Estes veículos estão equipados com motor que tem a capacidade de funcionar com mais de um tipo de combustível. No entanto, as pessoas que têm esse tipo de veículo, na hora do abastecimento, têm sempre a dúvida: álcool ou gasolina? Para avaliar o consumo desses combustíveis, realizou-se um percurso com um veículo flex, consumindo 40 litros de gasolina e no percurso de volta utilizou-se etanol. Foi considerado o mesmo consumo de energia tanto no percurso de ida quanto no de volta. O quadro resume alguns dados aproximados sobre esses combustíveis.\n\nDescrição do quadro: Quadro com dois combustíveis e seus valores de densidade em grama por mililitro e calor de combustão em quilocaloria por grama. Etanol: densidade: 0,8 calor de combustão: −6 Gasolina: densidade: 0,7 calor de combustão: −10\n\nO volume de etanol combustível, em litro, consumido no percurso de volta é mais próximo de",
