  "enunciado": "As pessoas que utilizam objetos cujo princípio de funcionamento é o mesmo do das alavancas aplicam uma força, chamada de força potente, em um dado ponto da barra, para superar ou equilibrar uma segunda força, chamada de resistente, em outro ponto da barra. Por causa das diferentes distâncias entre os pontos de aplicação das forças, potente e resistente, os seus efeitos também são diferentes. A figura mostra alguns exemplos desses objetos.\n\nDescrição da figura: A figura contém as imagens de cinco objetos: pinça, alicate, quebra-nozes, carrinho de mão e abridor de garrafa.\n\nEm qual dos objetos a força potente é maior que a força resistente?",
