  "enunciado": "Um artesão possui potes cilíndricos de tinta cujas medidas externas são 4 centímetros de diâmetro 6 centímetros de altura. Ele pretende adquirir caixas organizadoras para armazenar seus potes de tinta, empilhados verticalmente com tampas voltadas para cima, de forma que as caixas possam ser fechadas. No mercado, existem cinco opções de caixas organizadoras, com tampa, em formato de paralelepípedo reto retângulo, vendidas pelo mesmo preço, possuindo as seguintes dimensões internas:\n\nDescrição do quadro: Quadro com as informações: Modelo, Comprimento, Largura e Altura, em centímetro: Modelo I: Comprimento 8; Largura 8; Altura 40. Modelo II: Comprimento 8; Largura 20; Altura 14. Modelo III: Comprimento 18; Largura 5; Altura 35. Modelo IV: Comprimento 20; Largura 12; Altura 12. Modelo V: Comprimento 24; Largura 8; Altura 14.\n\nQual desses modelos o artesão deve adquirir para conseguir armazenar o maior número de potes por caixa?",
  "alternativas": [
   "I",
   "II",
   "III",
   "IV",
   "V"
  ],
