  "enunciado": "Um designer de jogos planeja um jogo que faz uso de um tabuleiro de dimensão n por n, com n maior ou igual a 2, no qual cada jogador, na sua vez, coloca uma peça sobre uma das casas vazias do tabuleiro. Quando uma peça é posicionada, a região formada pelas casas que estão na mesma linha ou coluna dessa peça é chamada de zona de combate dessa peça. Na figura está ilustrada a zona de combate de uma peça colocada em uma das casas de um tabuleiro de dimensão 8 por 8.\n\nDescrição da figura: Tabuleiro formado por oito colunas e oito linhas. Na terceira coluna e quinta linha há uma peça. As outras casas da terceira coluna e as outras casas da quinta linha formam a zona de combate.\n\nO tabuleiro deve ser dimensionado de forma que a probabilidade de se posicionar a segunda peça aleatoriamente, seguindo a regra do jogo, e esta ficar sobre a zona de combate da primeira, seja inferior a fração de numerador 1 e denominador 5. A dimensão mínima que o designer deve adotar para esse tabuleiro é",
  "alternativas": [
   "4 por 4.",
   "6 por 6.",
   "9 por 9.",
   "10 por 10.",
   "11 por 11."
  ],
  "resposta": 3,
