  "enunciado": "Com a descoberta de emissões de energia do rádio-226, por Marie Curie e Pierre Curie, o fenômeno foi denominado radiação alfa ou emissão alfa. Posteriormente, verificou-se que a emissão alfa na verdade são partículas correspondentes a núcleos de hélio formados por dois prótons e dois nêutrons. Assim, no decaimento alfa, um núcleo instável emite partículas alfa, tornando-se um núcleo mais estável, abre parêntese, núcleo, filho, fecha parêntese. Se um núcleo de rádio-226 emitir duas partículas alfa, o número de massa do núcleo filho será",
