  "enunciado": "O Protocolo de Montreal é um tratado internacional que diz respeito à defesa do meio ambiente. Uma de suas recomendações é a redução da utilização de substâncias propelentes, como os CFCs, abre parêntese, Cloro-Flúor-Carbono, fecha parêntese, em aerossóis e aparelhos de refrigeração. Essa recomendação visa",
