  "enunciado": "Para aumentar a arrecadação de seu restaurante que cobra por quilograma, o proprietário contratou um cantor e passou a cobrar dos clientes um valor fixo de couvert artístico, além do valor da comida. Depois, analisando as planilhas do restaurante, verificou-se em um dia que 30 clientes consumiram um total de 10 quilogramas de comida em um período de 1 hora, sendo que dois desses clientes pagaram 50 reais e 34 reais e consumiram 500 gramas e 300 gramas, respectivamente. Qual foi a arrecadação obtida pelo restaurante nesse período de 1 hora, em real?",
