  "enunciado": "Um síndico precisa pintar os muros, portões e calçamento de um edifício. Os pintores solicitaram três galões de tinta T1 para os muros, um galão de tinta T2 para os portões e dois galões de tinta T3 para o calçamento. Ele pesquisou o preço das tintas em cinco lojas diferentes, obtendo os seguintes valores, em real.\n\nDescrição do quadro: O quadro apresenta a loja e os correspondentes valores, em real, das tintas T1, T2 e T3, respectivamente. Na loja 1 a tinta T1 custa 82 reais, na T2 custa 134 reais e na T3 custa 202 reais. Na loja 2 a tinta T1 custa 80 reais, na T2 custa 122 reais e na T3 custa 214 reais. Na loja 3 a tinta T1 custa 85 reais, na T2 custa 115 reais e na T3 custa 209 reais. Na loja 4 a tinta T1 custa 88 reais, na T2 custa 132 reais e na T3 custa 199 reais. Na loja 5 a tinta T1 custa 90 reais, na T2 custa 116 reais e na T3 custa 202 reais.\n\nO síndico irá comprar as tintas numa única loja, escolhendo aquela em que o valor total da compra resulte no menor preço médio por galão. Com base nessas informações, a loja escolhida será",
