  "enunciado": "A fim de reforçar o orçamento familiar, uma dona de casa começou a produzir doces para revender. Cada receita é composta de quatro quintos de quilograma de amendoim e um quinto de quilograma de açúcar.\n\nO quilograma de amendoim custa 10 reais e o do açúcar, 2 reais. Porém, o açúcar teve um aumento e o quilograma passou a custar 2,20 reais. Para manter o mesmo custo com a produção de uma receita, essa dona de casa terá que negociar um desconto com o fornecedor de amendoim.\n\nNas condições estabelecidas, o novo valor do quilograma de amendoim deverá ser igual a",
