  "enunciado": "Um vidraceiro precisa construir tampos de vidro com formatos diferentes, porém com medidas de áreas iguais. Para isso, pede a um amigo que o ajude a determinar uma fórmula para o cálculo do raio R de um tampo de vidro circular com área equivalente à de um tampo de vidro quadrado de lado L. A fórmula correta é",
