  "enunciado": "Os alunos do curso de matemática de uma universidade desejam fazer uma placa de formatura, no formato de um triângulo equilátero, em que os seus nomes aparecerão dentro de uma região quadrada, inscrita na placa, conforme a figura.\n\nDescrição da figura: Quadrado inscrito em um triângulo equilátero.\n\nConsiderando que a área do quadrado, em que aparecerão os nomes dos formandos, mede 1 metro quadrado, qual é aproximadamente a medida, em metro, de cada lado do triângulo que representa a placa? (Utilize 1,7 como valor aproximado para raiz quadrada de 3).",
