  "enunciado": "Para identificar visualmente uma loja de pet shop, um empresário criou uma logomarca que se assemelha a uma marca deixada pela pegada de um gato, como na figura. O maior círculo tem medida de raio igual a 6 centímetros.\n\nO empresário pretende reproduzir o desenho em uma das paredes retangulares da loja. Para isso, fará a ampliação da logomarca utilizando a escala de 1 para 25.\n\nDescrição da Figura: Pegada estilizada de um gato, representada por quatro círculos e um segmento de círculo, todos no interior de um círculo maior.\n\nA área mínima, em metro quadrado, que a parede deverá ter para que a logomarca seja aplicada é",
