  "enunciado": "Os detergentes que usamos em nossas casas vão para os esgotos e muitos, quando não passam por estações de tratamento, descem diretamente para os rios, causando poluição. A solução tecnológica encontrada para resolver esse problema foi o desenvolvimento de detergentes cuja composição é mais facilmente eliminada dos ambientes aquáticos.\n\nOs detergentes que representam essa solução tecnológica são conhecidos como",
