  "enunciado": "Uma pessoa, antes de sair de casa para visitar um amigo, deslocando-se com o seu carro, verifica em um aplicativo para celulares quatro possibilidades de trajetos para fazer a sua viagem, obtendo os seguintes resultados quanto a distâncias e tempos de deslocamento em função do trânsito:\n• trajeto 1: distância de 25 km, deslocamento de 5 km a cada 14 minutos;\n• trajeto 2: distância de 20 km, deslocamento de 5 km a cada 20 minutos;\n• trajeto 3: distância de 32 km, deslocamento de 8 km a cada 15 minutos;\n• trajeto 4: distância de 36 km, deslocamento de 9 km a cada 18 minutos.\n\nA fim de gastar o menor tempo possível, qual trajeto essa pessoa deverá escolher?",
  "alternativas": [
   "1",
   "2",
   "3",
   "4"
  ],
  "resposta": 2,
