  "enunciado": "Sabe-se que as queimadas são fenômenos que podem ocorrer naturalmente. Entretanto, elas podem ser induzidas pelo ser humano ao atear fogo no mato para fazer, por exemplo, uma nova plantação. Para que esse fenômeno ocorra de forma natural, o tempo de uma determinada região deve estar predominantemente",
