  "enunciado": "Um estudante tem disponíveis 3 pedaços de arame que medem 3 cm, 4 cm e 5,1 cm cada. Ele pretende formar um triângulo com esses pedaços e analisar o maior de seus ângulos. Quatro colegas fizeram estas afirmações sobre a medida desse maior ângulo:\n• Alice: Deve ser obtuso, pois o triângulo com lados medindo 3, 4 e 5 cm é retângulo e 5,1 é maior que 5;\n• Bianca: Deve ser agudo, já que tem 3 medidas diferentes;\n• Celso: Deve ser reto, pois parece o triângulo pitagórico 3, 4, 5;\n• Dênis: Não será possível formar um triângulo com esses pedaços, pois 5,1 é maior que os outros dois números. Qual estudante fez a afirmativa correta?",
