  "enunciado": "Um pai combinou de dar a seu filho R$ 50,00 de mesada, mas, a cada bilhete vindo da escola avisando que ele não tinha feito o dever de casa, seriam descontados R$ 1,50 e, por outro lado, a cada bilhete de elogio, seriam acrescentados R$ 2,00 ao valor da mesada. O filho resolveu formular uma expressão que fornecesse o valor V, em real, que receberia de mesada, em função do número M de bilhetes informando não ter feito o dever de casa, e do número B de bilhetes de elogios recebidos da escola naquele mês. A expressão formulada foi",
  "alternativas": [
   "V = 50,00 + 2,00 × B + 1,50 × M",
   "V = 50,00 + 0,50 × B",
   "V = 50,00 + 2,00 × B − 1,50 × M",
   "V = 50,00 − 2,00 × M + 1,50 × B"
  ],
  "resposta": 2,
