  "enunciado": "Uma costureira produz vestidos sob encomenda a partir de dois tipos de tecidos, A e B. Os preços variam de acordo com o tamanho e o tecido utilizado:\n• vestidos feitos com o tecido A custam: R$ 50,00 no tamanho P, R$ 70,00 no tamanho M e R$ 100,00 no tamanho G;\n• vestidos feitos com o tecido B custam R$ 20,00 a mais que os de mesmo tamanho feitos com o tecido A. A fornecedora de tecidos dessa costureira aumentou o preço do tecido A, o que implicará um aumento de 10% sobre os preços dos vestidos feitos com ele. Para incentivar as vendas, a costureira decidiu oferecer um desconto nos preços dos vestidos confeccionados com o tecido B, de forma que eles se igualassem aos novos preços dos vestidos feitos com o tecido A. Qual desconto, em real, a costureira deverá oferecer em vestidos feitos com o tecido B nos tamanhos P, M e G, respectivamente?",
  "alternativas": [
   "5, 7 e 10.",
   "7, 9 e 12.",
   "10, 10 e 10.",
   "15, 13 e 10."
  ],
  "resposta": 3,
