  "enunciado": "O sal é uma substância importante na alimentação humana e pode ser extraído da água do mar. A água salgada vai para enormes tanques, cada um com uma área igual a dez campos de futebol e profundidade de apenas 20 centímetros. Qual método de separação de misturas é utilizado para essa extração?",
