  "enunciado": "Um funcionário recebe um salário mensal de R$ 1 200,00 registrado em carteira. Em determinado mês, o contracheque desse funcionário apresenta os seguintes acréscimos e descontos, calculados sobre o seu salário:\n• INSS: desconto de R$ 133,20;\n• faltas não justificadas: desconto de R$ 80,00;\n• vale-alimentação: acréscimo de R$ 300,00;\n• seguro-saúde: desconto de R$ 6,00. Nesse mês, a quantia que o funcionário receberá, em real, é",
