  "enunciado": "Um arquiteto deseja utilizar uma tela, no formato triangular, com base medindo 10 dm e altura 8 dm, para a realização de um projeto. Ele não obteve sucesso na busca desse material, encontrando, apenas, telas retangulares de diferentes medidas. Então, resolveu reestruturar seu projeto, optando por uma tela retangular de comprimento 5 dm e que tenha área igual à área da tela inicialmente desejada. Com base nessas informações, a tela a ser escolhida pelo arquiteto deverá possuir altura, em dm, igual a",
