  "enunciado": "Em uma reunião de uma cooperativa, há 600 associados presentes com direito a voto. Eles discutem a venda ou não de um imóvel, e as duas únicas opções de voto são favorável ou não favorável à venda. A decisão pela venda ou não será a que tiver o maior número de votos, e 480 dos associados presentes já votaram. Até o momento, 60% dos votos foram para não vender o imóvel e 40% para vendê-lo. Os demais associados declararão seus votos sabendo desse resultado parcial. Um dos presentes, que já votou a favor da venda, pretende convencer outras pessoas que ainda não votaram para garantir que a decisão final seja pela venda do terreno. Para que isso ocorra, o número mínimo de sócios que ele deve convencer a votar a favor da venda é",
