  "enunciado": "Em um evento, estava sendo cobrada uma entrada de 20 reais para estudante e 30 reais para não estudante. Nesse evento houve um número Z de estudantes e um número Y de não estudantes. A expressão algébrica que representa o valor total arrecadado nesse evento é",
