  "enunciado": "O Sr. José precisa de R$ 10 000,00 para fazer uma reforma em sua residência e entra em contato com os bancos A e B, recebendo as seguintes propostas:\n• banco A: Taxa de 2% ao mês. Tempo do empréstimo: 24 meses;\n• banco B: Taxa de 4% ao ano. Tempo do empréstimo: 2 anos. Supondo que o empréstimo, nos dois casos, seja oferecido sob o regime de juros simples, o valor dos juros cobrados pelo banco A em relação ao valor dos juros cobrados pelo banco B é",
