  "enunciado": "Uma pessoa enche o pneu de seu automóvel usando o compressor de ar de um posto de gasolina. Quando o pneu atinge o seu máximo volume, a mangueira do compressor é desconectada do pneu. Quando o pneu atinge o volume máximo, o ar no seu interior tem",
