  "enunciado": "Na sequência de Fibonacci (1, 1, 2, 3, 5, 8, ...), cada um de seus termos, a partir do terceiro, é igual à soma dos dois termos imediatamente anteriores. Essa sequência pode ser utilizada como uma forma de aproximação na conversão de quilômetro para milha (unidade de comprimento utilizada em alguns países de língua inglesa). Veja a relação. 8 km ↔ 5 mi 13 km ↔ 8 mi 21 km ↔ 13 mi 34 km ↔ 21 mi 55 km ↔ 34 mi Então, se o velocímetro de um carro importado estiver assinalando 55 mi/h, essa velocidade, em quilômetro por hora, será mais próxima de",
