  "enunciado": "Na escola de Maria, o ano letivo é dividido em bimestres. A nota bimestral é calculada pela média aritmética das notas obtidas nas quatro avaliações de 25 pontos aplicadas ao longo do bimestre. Caso essa média seja inferior a 15 pontos, o aluno é obrigado a participar da recuperação bimestral. Maria fez três avaliações em um bimestre, e a média aritmética de suas notas nessas três avaliações foi de 12 pontos. Para que não precise participar da recuperação nesse bimestre, a nota mínima que Maria precisa tirar na quarta avaliação bimestral é",
