  "enunciado": "Pamonha é um dos deliciosos pratos típicos dos estados de Goiás e Minas Gerais. A verdadeira pamonha é feita à base de milho verde e leite, acrescidos de sal ou açúcar, queijo ou linguiça, e cozida na palha do milho. Antigamente a pamonha só existia numa época do ano, pois só se semeava e colhia o milho na estação chuvosa. Desde os anos 1970, goianos e mineiros podem se deliciar com pamonhas o ano todo, devido a uma nova tecnologia. A inovação tecnológica que possibilitou a expansão do período de plantio foi a",
