  "enunciado": "Sobras de alimentos são resíduos orgânicos compostos por material biológico e, por isso, ricos em nutrientes que podem retornar para a natureza, completando o ciclo da matéria. Essa ciclagem pode ser feita até mesmo em casa, pelo processo de compostagem, e o produto gerado por essa técnica pode ser utilizado como adubo em hortas caseiras. A utilização desse adubo fortalece as plantas porque",
