  "enunciado": "O planejamento familiar, ou seja, o número de filhos que o casal deseja ter, pode ser feito com o uso de diversos métodos anticoncepcionais. O método que, além de atender ao planejamento citado, também contribui para evitar doenças sexualmente transmissíveis é o(a)",
