  "enunciado": "A gordura trans é um ingrediente utilizado em alguns alimentos para dar mais sabor. Porém, é difícil de digerir e pode causar problemas de saúde. O Ministério da Saúde adverte que não há níveis seguros de ingestão desse tipo de gordura. Uma mãe fica preocupada após seu filho ingerir todo o pacote de um biscoito, que tem 20 unidades. As informações nutricionais apresentadas nesse pacote indicam que cada porção equivalente a 5 unidades de biscoito tem 2 gramas de gordura trans. A quantidade, em grama, de gordura trans proveniente do pacote de biscoitos ingerido pela criança é",
