  "enunciado": "Os pesticidas sintéticos, isto é, produzidos em laboratório, são substâncias que podem matar ou controlar diferentes organismos indesejáveis para as lavouras. Tais produtos podem ser classificados em: inseticidas, que atuam sobre insetos; fungicidas, que atuam sobre fungos; e herbicidas, que atuam sobre plantas indesejadas. O uso prolongado dos pesticidas sintéticos nas lavouras tem como consequência o(a)",
